INSERT INTO public.diet_protocols (id, name, description, protocol_type, foods_include, foods_avoid, food_groups_include, food_groups_avoid, target_mechanisms, target_root_causes, target_conditions, evidence_level, citation, difficulty, meal_examples) VALUES
('low-gi-anti-inflammatory', 'Low Glycemic Anti-Inflammatory', 'Focuses on low glycemic index foods and anti-inflammatory nutrients to reduce AGE formation and systemic inflammation', 'low_glycemic', ARRAY['leafy greens','fatty fish','berries','olive oil','nuts','seeds','avocado','sweet potatoes','quinoa','legumes'], ARRAY['white bread','pasta','white rice','sugar','processed snacks','fried foods','soda','high-glycemic fruits'], ARRAY['vegetables','healthy fats','lean protein','complex carbs'], ARRAY['refined grains','added sugars','trans fats','processed foods'], ARRAY['glycation','inflammation','oxidative_stress'], ARRAY['insulin_resistance','inflammation'], ARRAY['acne-vulgaris','premature-aging','rosacea'], 'A', 'Low GI diet reduces AGE formation by ~30% in clinical studies', 'moderate', '{"breakfast":["vegetable omelet with avocado","steel-cut oats with berries"],"lunch":["grilled salmon salad with olive oil dressing","quinoa bowl with roasted vegetables"],"dinner":["herb-crusted chicken with sweet potato","lentil curry with cauliflower rice"],"snacks":["handful of walnuts","carrot sticks with hummus","green apple with almond butter"]}'),
('elimination-dairy-free', 'Dairy-Free Elimination', 'Removes dairy to reduce IGF-1 and hormonal acne triggers; supports clearer skin for dairy-sensitive individuals', 'elimination', ARRAY['plant-based milks','leafy greens for calcium','fermented foods','lean proteins'], ARRAY['milk','cheese','yogurt','butter','ice cream','whey protein'], ARRAY['plant-based foods','fermented foods','calcium-rich greens'], ARRAY['dairy products','whey supplements'], ARRAY['hormonal','inflammatory'], ARRAY['hormonal_imbalance','inflammation'], ARRAY['acne-vulgaris','hormonal-acne'], 'B', 'Dairy elimination shows improvement in acne severity in controlled studies', 'moderate', '{"breakfast":["oatmeal with almond milk and berries","tofu scramble with vegetables"],"lunch":["turkey and avocado wrap","quinoa salad with chickpeas"],"dinner":["grilled chicken with roasted vegetables","stir-fry with coconut aminos"],"snacks":["rice cakes with almond butter","carrots and guacamole"]}'),
('elimination-gluten-free', 'Gluten-Free Elimination', 'Removes gluten to reduce gut permeability and systemic inflammation for gluten-sensitive individuals', 'elimination', ARRAY['rice','quinoa','buckwheat','sweet potatoes','vegetables','fruits','lean proteins'], ARRAY['wheat','barley','rye','most breads','pasta','cereals'], ARRAY['naturally gluten-free grains','vegetables','fruits','lean proteins'], ARRAY['wheat products','barley','rye','most processed foods'], ARRAY['gut_permeability','inflammatory'], ARRAY['leaky_gut','inflammation'], ARRAY['atopic-dermatitis','psoriasis','acne-vulgaris'], 'B', 'Gluten elimination improves gut barrier function in sensitive individuals', 'moderate', '{"breakfast":["buckwheat pancakes with berries","smoothie with spinach and banana"],"lunch":["grilled fish with rice and vegetables","stuffed bell peppers with quinoa"],"dinner":["chicken stir-fry with tamari","zucchini noodles with pesto"],"snacks":["rice cakes with avocado","fruit salad"]}'),
('autoimmune-protocol', 'Autoimmune Protocol (AIP)', 'Comprehensive elimination diet targeting immune dysregulation and gut healing; strict initial phase with gradual reintroduction', 'autoimmune', ARRAY['quality meats','organ meats','sea vegetables','fermented foods','leafy greens','root vegetables'], ARRAY['grains','dairy','legumes','nuts','seeds','nightshades','eggs','processed foods'], ARRAY['quality animal proteins','vegetables','fermented foods'], ARRAY['grains','dairy','legumes','nuts','seeds','nightshades','eggs'], ARRAY['immune_dysregulation','gut_permeability','inflammatory'], ARRAY['autoimmune_activations','leaky_gut','inflammation'], ARRAY['psoriasis','atopic-dermatitis'], 'B', 'AIP shows symptom reduction in autoimmune conditions including psoriasis', 'challenging', '{"breakfast":["salmon patties with spinach","bone broth with vegetables"],"lunch":["grass-fed beef with roasted root vegetables","sardine salad with avocado"],"dinner":["herb-roasted chicken with sweet potato","lamb chops with steamed greens"],"snacks":["bone broth","fermented carrots","coconut flakes"]}'),
('gut-healing-protocol', 'Gut Healing Protocol', 'Targets dysbiosis and gut permeability through specific foods and nutrients that nourish the gut microbiome and repair intestinal lining', 'gut_healing', ARRAY['bone broth','fermented vegetables','prebiotic fibers','wild-caught fish','pasture-raised meats','cooked vegetables'], ARRAY['processed foods','excess sugar','artificial sweeteners','excess alcohol','NSAIDs'], ARRAY['fermented foods','prebiotic foods','collagen-rich foods','omega-3 rich foods'], ARRAY['processed foods','refined sugars','artificial additives','excess alcohol'], ARRAY['dysbiosis','gut_permeability','inflammatory'], ARRAY['gut_dysbiosis','leaky_gut','inflammation'], ARRAY['acne-vulgaris','rosacea','atopic-dermatitis'], 'B', 'Gut healing protocols improve skin conditions through microbiome modulation', 'moderate', '{"breakfast":["bone broth with poached eggs","chia pudding with berries"],"lunch":["wild salmon with sauerkraut","vegetable soup with bone broth"],"dinner":["pasture-raised chicken with roasted vegetables","beef stew with root vegetables"],"snacks":["fermented carrots","gelatin gummies","kombucha"]}'),
('hormone-balancing', 'Hormone Balancing Diet', 'Supports endocrine health through nutrient-dense foods that promote hormonal balance and reduce insulin resistance', 'hormone_balancing', ARRAY['cruciferous vegetables','healthy fats','fiber-rich foods','quality protein','flaxseeds','wild-caught fish'], ARRAY['excess sugar','refined carbs','conventional dairy','soy products','excess caffeine','alcohol'], ARRAY['cruciferous vegetables','healthy fats','fiber','quality protein','omega-3'], ARRAY['refined sugars','conventional dairy','excess soy','excess caffeine'], ARRAY['hormonal','metabolic'], ARRAY['hormonal_imbalance','insulin_resistance','estrogen_dominance'], ARRAY['hormonal-acne','melasma','premature-aging'], 'B', 'Nutrient-dense diets support hormonal balance and improve hormone-related skin conditions', 'moderate', '{"breakfast":["green smoothie with flaxseeds","vegetable frittata with avocado"],"lunch":["grilled chicken salad with olive oil","salmon with roasted broccoli"],"dinner":["turkey meatballs with zucchini noodles","stir-fry with cruciferous vegetables"],"snacks":["handful of pumpkin seeds","celery with almond butter","berries"]}'),
('mediterranean-skin', 'Mediterranean for Skin', 'Adaptation of the Mediterranean diet optimized for skin health through polyphenols, omega-3s, and antioxidant-rich foods', 'mediterranean', ARRAY['olive oil','fatty fish','nuts','seeds','colorful vegetables','legumes','whole grains','herbs'], ARRAY['processed meats','refined grains','excess sugar','trans fats','excess alcohol'], ARRAY['healthy fats','vegetables','whole grains','lean proteins','herbs'], ARRAY['processed meats','refined grains','added sugars','trans fats'], ARRAY['oxidative_stress','inflammatory','cardiovascular'], ARRAY['inflammation','oxidative_stress'], ARRAY['premature-aging','rosacea','acne-vulgaris'], 'A', 'Mediterranean diet consistently ranks highest for anti-inflammatory and skin health benefits', 'easy', '{"breakfast":["greek yogurt with walnuts and honey","vegetable omelet with olive oil"],"lunch":["mediterranean salad with feta and olives","grilled fish with vegetables"],"dinner":["herb-crusted lamb with tabbouleh","stuffed peppers with rice and pine nuts"],"snacks":["hummus with vegetables","handful of almonds","fresh figs"]}'),
('ketogenic-metabolic', 'Therapeutic Ketogenic', 'Low-carbohydrate, high-fat diet for metabolic reset targeting insulin resistance, mitochondrial dysfunction, and neuroinflammation', 'ketogenic', ARRAY['avocado','coconut oil','olive oil','fatty fish','eggs','grass-fed meats','low-carb vegetables','nuts'], ARRAY['grains','sugar','starchy vegetables','most fruits','processed foods','legumes'], ARRAY['healthy fats','quality proteins','low-carb vegetables'], ARRAY['grains','sugar','starchy vegetables','high-carb foods'], ARRAY['insulin_resistance','mitochondrial_dysfunction','neuroinflammation'], ARRAY['insulin_resistance','mitochondrial_dysfunction'], ARRAY['acne-vulgaris','premature-aging','inflammation'], 'B', 'Ketogenic diets improve metabolic markers and reduce inflammation markers', 'challenging', '{"breakfast":["avocado and eggs with olive oil","bulletproof coffee with MCT oil"],"lunch":["salmon salad with avocado dressing","cobb salad with bacon and egg"],"dinner":["ribeye steak with buttered asparagus","roasted chicken with cauliflower mash"],"snacks":["macadamia nuts","olives","celery with almond butter"]}')
