('resveratrol', 'evening with fat', 'continuous', 12, ARRAY['nmn','nr'], ARRAY['blood thinners'], 'premature-aging', '250-500mg/day', 'Sirtuin activation for longevity and anti-inflammatory', 'B'),
('sulforaphane', 'morning', 'continuous', 12, ARRAY[''], ARRAY[''], 'acne-vulgaris', '10-30mg/day', 'Nrf2 activation for antioxidant defense and detoxification', 'A'),
('lactobacillus-rhamnosus', 'morning empty stomach', 'continuous', 12, ARRAY['saccharomyces-boulardii'], ARRAY['antibiotics'], 'acne-vulgaris', '10-20B CFU/day', 'Gut-skin axis support for acne and rosacea', 'A'),
('saccharomyces-boulardii', 'evening', 'continuous', 12, ARRAY['lactobacillus-rhamnosus'], ARRAY['antifungals'], 'atopic-dermatitis', '250-500mg/day', 'Gut barrier and anti-inflammatory for atopic skin', 'A'),
('l-glutamine', 'morning empty stomach', 'continuous', 8, ARRAY['probiotics-multi'], ARRAY[''], 'atopic-dermatitis', '5-10g/day', 'Gut barrier repair and intestinal permeability reduction', 'B'),
('zinc', 'with meals', 'continuous', 12, ARRAY['vitamin-d3'], ARRAY['copper supplements','tetracyclines'], 'acne-vulgaris', '15-30mg/day picolinate', 'Immune function, wound healing, anti-inflammatory for acne', 'A'),
('selenium', 'morning with food', 'continuous', 12, ARRAY['zinc'], ARRAY[''], 'premature-aging', '100-200mcg/day selenomethionine', 'Thyroid support and antioxidant via glutathione peroxidase', 'B'),
