INSERT INTO public.psychoderm_protocols (id, name, description, protocol_type, conditions_treated, stress_triggers, duration_minutes, frequency, instructions, evidence_level, citation, dosage, interactions, side_effects) VALUES
('mbsr-skin', 'Mindfulness-Based Stress Reduction (MBSR)', '8-week structured mindfulness program adapted for skin conditions; reduces inflammatory markers and improves eczema/psoriasis flares', 'mindfulness', ARRAY['atopic-dermatitis','psoriasis','acne-vulgaris'], ARRAY['work','health anxiety','social stress'], 20, 'daily', '1. Find a quiet space and sit comfortably\n2. Focus on breath for 10 minutes\n3. Body scan for 10 minutes, noting sensations without judgment\n4. When mind wanders, gently return to breath\n5. Practice daily at same time', 'A', 'MBSR reduces cortisol and inflammatory cytokines in dermatology patients', NULL, NULL, NULL),
('cbt-acne', 'CBT for Acne-Related Anxiety', 'Cognitive behavioral therapy targeting the stress-acne-anxiety cycle and skin-picking behaviors', 'cbt', ARRAY['acne-vulgaris','dermatillomania'], ARRAY['social anxiety','appearance concerns','perfectionism'], 45, 'weekly', '1. Identify triggers for skin-focused anxiety\n2. Challenge catastrophic thoughts about appearance\n3. Develop alternative coping strategies to skin picking\n4. Exposure to social situations without camouflage\n5. Track mood and skin correlation in journal', 'A', 'CBT significantly reduces anxiety and improves quality of life in acne patients', NULL, NULL, NULL),
('breathwork-478', '4-7-8 Breathing Protocol', 'Simple breathwork technique that activates parasympathetic nervous system and reduces cortisol in 5 minutes', 'breathwork', ARRAY['acne-vulgaris','rosacea','atopic-dermatitis'], ARRAY['acute stress','work pressure','sleep anxiety'], 5, 'as_needed', '1. Inhale through nose for 4 counts\n2. Hold breath for 7 counts\n3. Exhale completely through mouth for 8 counts\n4. Repeat cycle 4 times\n5. Use during stress moments or before bed', 'B', '4-7-8 breathing activates vagal tone and reduces acute cortisol spikes', NULL, NULL, NULL),
('box-breathing', 'Box Breathing (Navy SEAL)', 'Structured equal-duration breathing for acute stress reduction and autonomic regulation', 'breathwork', ARRAY['acne-vulgaris','premature-aging'], ARRAY['acute stress','performance anxiety'], 5, 'as_needed', '1. Inhale for 4 counts\n2. Hold for 4 counts\n3. Exhale for 4 counts\n4. Hold empty for 4 counts\n5. Repeat for 5 minutes\n6. Use before high-stress events', 'B', 'Box breathing demonstrates measurable HRV improvement and stress reduction', NULL, NULL, NULL),
('body-scan', 'Body Scan Meditation', 'Progressive relaxation technique reducing muscle tension and improving sleep quality for skin repair', 'meditation', ARRAY['atopic-dermatitis','premature-aging'], ARRAY['physical tension','sleep issues'], 15, 'daily', '1. Lie down in comfortable position\n2. Starting at toes, notice sensations in each body part\n3. Move slowly up through legs, torso, arms, face\n4. Release tension in each area with exhale\n5. Practice before sleep for maximum benefit', 'B', 'Body scan meditation improves sleep quality and reduces muscle tension', NULL, NULL, NULL),
('journaling-pm', 'Evening Stress Journaling', 'Cognitive offloading technique to reduce rumination-related skin flares', 'journaling', ARRAY['acne-vulgaris','psoriasis','atopic-dermatitis'], ARRAY['rumination','work stress','relationship stress'], 10, 'daily', '1. Set timer for 10 minutes\n2. Write freely about stressors without editing\n3. Identify one actionable step for tomorrow\n4. Close journal and mentally "park" concerns\n5. Practice only in evening, never before work', 'B', 'Expressive writing reduces rumination and improves sleep quality', NULL, NULL, NULL),
('biofeedback-hrv', 'HRV Biofeedback', 'Direct autonomic nervous system training with measurable stress reduction using heart rate variability', 'biofeedback', ARRAY['rosacea','acne-vulgaris','psoriasis'], ARRAY['chronic stress','work pressure','anxiety'], 20, 'daily', '1. Use HRV monitor (Oura, Apple Watch, or dedicated device)\n2. Practice resonant breathing at 5.5-6 breaths/minute\n3. Monitor real-time HRV feedback\n4. Aim for coherent heart rhythm pattern\n5. Track HRV trends over weeks', 'A', 'HRV biofeedback demonstrates robust evidence for stress reduction and autonomic balance', NULL, NULL, NULL),
('ashwagandha-psych', 'Ashwagandha (KSM-66) for Stress-Skin', 'Adaptogenic herb reducing cortisol 28% and improving stress-mediated acne/eczema', 'adaptogen', ARRAY['acne-vulgaris','atopic-dermatitis','premature-aging'], ARRAY['chronic stress','work burnout','anxiety'], NULL, 'daily', 'Take 300-600mg KSM-66 extract daily with evening meal. Monitor cortisol response after 4 weeks. Combine with stress management practices.', 'A', 'KSM-66 reduces cortisol 28% in randomized trials and improves stress-related skin conditions', '300-600mg/day KSM-66', ARRAY['thyroid medications','sedatives'], ARRAY['mild GI upset']),
('rhodiola-psych', 'Rhodiola Rosea for Fatigue-Skin', 'Adaptogen reducing fatigue-related skin dullness and supporting HPA axis', 'adaptogen', ARRAY['premature-aging','dullness'], ARRAY['chronic fatigue','work stress','overtraining'], NULL, 'daily', 'Take 200-400mg standardized extract in morning on empty stomach. Cycle 5 days on, 2 days off. Avoid evening use (may interfere with sleep).', 'B', 'Rhodiola reduces fatigue and improves stress resilience with HPA axis modulation', '200-400mg/day', ARRAY[''], ARRAY['mild insomnia if taken late']),
('l-theanine-psych', 'L-Theanine for Anxiety-Skin', 'Promotes alpha brain waves and reduces stress without sedation', 'supplement', ARRAY['acne-vulgaris','atopic-dermatitis'], ARRAY['anxiety','acute stress','social situations'], NULL, 'daily', 'Take 200-400mg L-theanine as needed for acute stress or daily for chronic anxiety. Can combine with morning coffee to reduce jitters.', 'B', 'L-theanine increases alpha wave activity and reduces subjective stress without sedation', '200-400mg/day', ARRAY[''], ARRAY['rare headache']),
('magnesium-glycinate', 'Magnesium Glycinate for Stress', 'Calms nervous system and improves sleep-mediated skin repair', 'supplement', ARRAY['atopic-dermatitis','premature-aging','acne-vulgaris'], ARRAY['sleep issues','physical tension','anxiety'], NULL, 'daily', 'Take 400mg magnesium glycinate 1-2 hours before bed. Combine with sleep hygiene practices for maximum benefit.', 'A', 'Magnesium glycinate improves sleep quality and reduces nocturnal cortisol', '400mg before bed', ARRAY['some antibiotics','blood pressure meds'], ARRAY['mild drowsiness']),
('therapy-referral', 'Dermatologist + Therapist Referral', 'For severe psychodermatological conditions requiring professional mental health support', 'therapy_referral', ARRAY['dermatillomania','trichotillomania','severe anxiety','depression-related-skin'], ARRAY['compulsive behaviors','severe anxiety','depression'], NULL, 'as_needed', 'Refer to therapist specializing in psychodermatology or body-focused repetitive behaviors. Coordinate care with dermatologist for integrated treatment plan.', 'A', 'Psychodermatology referrals show significant improvement in quality of life for severe cases', NULL, NULL, NULL)
INSERT INTO public.post_procedure_protocols (id, procedure_type, name, description, pre_protocol, post_protocol, supplements_to_avoid, supplements_to_add, actives_to_avoid, actives_to_resume_timing, evidence_level, citation) VALUES
('post-microneedling', 'microneedling', 'Microneedling Recovery Protocol', 'Pre and post-procedure protocol for microneedling to optimize collagen induction and minimize complications', '{"avoid":["retinol","vitamin A","AHAs"],"timing":"72h before","supplement":["avoid blood thinners"],"alcohol":"none 48h"}', '{"immediate":["gentle cleanser only","no makeup","no sunscreen 4h"],"day_1_3":["hyaluronic acid serum","peptide serum","no actives"],"day_4_7":["gentle vitamin C","light moisturizer"],"week_2_plus":["resume retinol gradually","full routine"]}', ARRAY['blood thinners','fish oil','vitamin E'], ARRAY['arnica','bromelain'], ARRAY['retinol','AHA','BHA','vitamin C'], '7 days', 'A', 'Microneedling protocols support optimal collagen induction and barrier recovery'),
('post-chemical-peel', 'chemical_peel', 'Chemical Peel Recovery Protocol', 'Recovery protocol based on peel depth for optimal healing and results', '{"avoid":["retinol","waxing","exfoliants"],"timing":"5-7d before"}', '{"immediate":["gentle cleanser only 48h","no picking"],"day_1_3":["no actives","barrier cream","SPF 50+"],"day_4_7":["superficial: resume actives day 3","medium: resume actives day 7"],"week_2_plus":["deep peels: resume actives day 14","full routine"]}', ARRAY['blood thinners'], ARRAY['vitamin C','zinc'], ARRAY['retinol','AHA','BHA','vitamin C'], '3-14 days (depth dependent)', 'A', 'Peel depth determines recovery timeline and actives reintroduction schedule'),
('post-laser-fraxel', 'laser_fraxel', 'Fraxel Laser Recovery Protocol', 'Intensive recovery for fractional laser resurfacing', '{"avoid":["retinol","sun exposure"],"timing":"retinol 14d before, no sun 30d before"}', '{"immediate":["cooling + barrier repair","no actives"],"day_1_7":["gentle cleanser","barrier repair cream","no actives","SPF 50+"],"day_8_14":["gentle vitamin C","light moisturizer"],"week_2_plus":["resume actives gradually"]}', ARRAY['blood thinners','fish oil'], ARRAY['arnica','vitamin C','zinc'], ARRAY['retinol','AHA','BHA','vitamin C'], '14 days', 'A', 'Fraxel requires extended barrier repair and sun avoidance for optimal outcomes'),
('post-laser-ipl', 'laser_ipl', 'IPL Recovery Protocol', 'Recovery protocol for intense pulsed light treatments', '{"avoid":["sun exposure","self-tanner"],"timing":"no sun 30d before, no self-tanner 14d before"}', '{"immediate":["gentle care 48h","pigment may darken before flaking"],"day_1_3":["no picking","gentle moisturizer","SPF 50+"],"day_4_7":["resume gentle routine","no harsh actives"],"week_2_plus":["full routine","maintain SPF"]}', ARRAY['blood thinners'], ARRAY['vitamin C'], ARRAY['retinol','AHA'], '7 days', 'A', 'IPL requires careful sun avoidance and gentle care for pigment management'),
('post-botox', 'botox', 'Botox/Dysport Recovery Protocol', 'Post-injection protocol to optimize results and minimize spread', '{"avoid":["alcohol","blood thinners"],"timing":"no alcohol 48h, no blood thinners 7d"}', '{"immediate":["no lying flat 4h","no exercise 24h","no rubbing area 24h"],"day_1_3":["gentle cleansing","no facial massage","no heat exposure"],"day_4_7":["resume normal routine","no facial treatments"],"week_2_plus":["full results visible","maintain skincare"]}', ARRAY['blood thinners','fish oil'], ARRAY['arnica'], ARRAY[''], '24 hours', 'A', 'Botox post-care prevents product migration and optimizes results'),
('post-filler', 'filler', 'Dermal Filler Recovery Protocol', 'Recovery to minimize bruising and ensure proper settling', '{"avoid":["alcohol","blood thinners"],"timing":"no alcohol 48h, no blood thinners 7d","supplement":["arnica 3d prior"]}', '{"immediate":["ice 10min on/off day 1","no exercise 24h","sleep elevated"],"day_1_3":["gentle care","no facial massage","no extreme temperatures"],"day_4_7":["no dental work","monitor for lumps"],"week_2_plus":["no dental work 2w","full routine"]}', ARRAY['blood thinners','fish oil','vitamin E'], ARRAY['arnica','bromelain','vitamin K'], ARRAY['strong acids','retinoids near injection sites'], '7 days', 'A', 'Filler post-care minimizes bruising and ensures proper product integration'),
('post-prp', 'prp', 'PRP (Vampire Facial) Recovery Protocol', 'Recovery for platelet-rich plasma facial treatments', '{"avoid":["blood thinners","alcohol"],"timing":"no blood thinners 7d, no alcohol 48h"}', '{"immediate":["no makeup 24h","gentle care 48h"],"day_1_3":["no actives","gentle cleanser","SPF 50+"],"day_4_7":["resume gentle vitamin C","light moisturizer"],"week_2_plus":["resume actives day 5-7","full routine"]}', ARRAY['blood thinners','fish oil'], ARRAY['vitamin C','zinc'], ARRAY['retinol','AHA','BHA'], '5-7 days', 'A', 'PRP requires minimal intervention for optimal platelet-mediated healing'),
('post-rf-microneedling', 'rf_microneedling', 'RF Microneedling Recovery Protocol', 'Combined radiofrequency and microneedling recovery', '{"avoid":["retinol","sun exposure"],"timing":"retinol 72h before, no sun 14d before"}', '{"immediate":["barrier repair","no actives","possible swelling 48h"],"day_1_5":["gentle cleanser","barrier cream","no actives","SPF 50+"],"day_6_7":["gentle vitamin C","light moisturizer"],"week_2_plus":["resume actives gradually"]}', ARRAY['blood thinners'], ARRAY['arnica','vitamin C'], ARRAY['retinol','AHA','BHA','vitamin C'], '7 days', 'A', 'RF microneedling requires extended barrier repair due to combined thermal injury'),
('post-hifu', 'hifu', 'HIFU Recovery Protocol', 'High-intensity focused ultrasound recovery protocol', '{"avoid":["fillers in area 6mo"],"timing":"no fillers in treatment area 6 months prior"}', '{"immediate":["may be sore 48h","no NSAIDs"],"day_1_3":["gentle care","no massage","no extreme temperatures"],"day_4_7":["monitor for numbness","gentle routine"],"week_2_plus":["gradual improvement over 3-6 months","full routine"]}', ARRAY['nsaids'], ARRAY['arnica'], ARRAY['strong actives'], '7 days', 'B', 'HIFU results develop over 3-6 months; minimal acute care needed'),
('post-thread-lift', 'thread_lift', 'Thread Lift Recovery Protocol', 'Recovery to ensure thread stability and minimize complications', '{"avoid":["blood thinners","alcohol"],"timing":"no blood thinners 7d, no alcohol 48h"}', '{"immediate":["sleep on back 7d","no wide mouth opening 2w","no dental work 2w"],"day_1_3":["gentle care","no facial massage","ice if needed"],"day_4_7":["monitor for infection signs","gentle routine"],"week_2_plus":["avoid aggressive facial treatments 4w","full routine"]}', ARRAY['blood thinners','fish oil'], ARRAY['arnica','vitamin C'], ARRAY['strong acids','aggressive exfoliants'], '14 days', 'A', 'Thread lifts require strict movement restrictions for optimal thread integration')
INSERT INTO public.fitzpatrick_adjustments (fitzpatrick_type, category, adjustment_type, target, value, rationale, evidence_level) VALUES
