(1, 'uv_protection', 'avoid', 'peak_sun', 'Avoid peak sun (10 AM - 4 PM)', 'Type I skin cannot safely tolerate midday UV exposure', 'A'),
(1, 'actives', 'prefer', 'retinol_start', 'Start low (0.025%), gradual introduction', 'Type I skin is prone to irritation and erythema from active ingredients', 'A'),
(1, 'actives', 'avoid', 'aggressive_aha', 'Avoid high-concentration glycolic acid initially', 'High-concentration AHAs can cause excessive irritation in Type I skin', 'B'),
(1, 'supplements', 'add', 'vitamin_d', 'Extra vitamin D 5000 IU daily', 'Type I skin synthesizes minimal vitamin D due to sun avoidance', 'A'),
(2, 'uv_protection', 'add', 'spf_level', 'SPF 50 daily, reapply every 2 hours', 'Type II skin burns easily and requires strong UV protection', 'A'),
(2, 'uv_protection', 'prefer', 'sun_timing', 'Early morning or late afternoon only', 'Type II skin tolerates minimal direct sun exposure', 'A'),
(2, 'actives', 'prefer', 'retinol_start', 'Low-medium retinol (0.025-0.05%)', 'Standard retinol introduction with monitoring for erythema', 'A'),
(2, 'actives', 'add', 'patch_test', 'Patch test all new actives', 'Type II skin is prone to contact reactions', 'B'),
(2, 'supplements', 'add', 'vitamin_d', 'Vitamin D 4000 IU daily', 'Type II skin has limited vitamin D synthesis capacity', 'A'),
(3, 'uv_protection', 'add', 'spf_level', 'SPF 30-50 daily', 'Type III skin burns sometimes; moderate protection needed', 'A'),
(3, 'actives', 'prefer', 'retinol_start', 'Medium retinol (0.05%) standard', 'Type III skin tolerates standard retinol concentrations', 'A'),
(3, 'actives', 'add', 'aha_monitor', 'Monitor for PIH with AHA use', 'Type III skin can develop post-inflammatory hyperpigmentation', 'A'),
(3, 'procedures', 'prefer', 'laser_settings', 'Standard laser settings with PIH monitoring', 'Type III skin requires careful laser parameter selection', 'A'),
(3, 'supplements', 'add', 'vitamin_d', 'Vitamin D 3000 IU daily', 'Moderate vitamin D synthesis capacity', 'B'),
(4, 'uv_protection', 'add', 'spf_level', 'SPF 30 daily, focus on hyperpigmentation', 'Type IV skin rarely burns but prone to hyperpigmentation', 'A'),
(4, 'actives', 'prefer', 'retinol_concentration', 'Medium-high retinol (0.05-0.1%)', 'Type IV skin generally tolerates higher retinol concentrations', 'A'),
(4, 'actives', 'avoid', 'aggressive_laser', 'Careful with aggressive fractional lasers', 'Type IV skin has higher PIH risk with aggressive energy-based treatments', 'A'),
(4, 'procedures', 'prefer', 'treatment_type', 'Prefer chemical over aggressive light-based', 'Chemical treatments have more predictable outcomes in Type IV skin', 'B'),
(4, 'supplements', 'add', 'vitamin_d', 'Vitamin D 2000-3000 IU daily', 'Moderate vitamin D synthesis', 'B'),
(5, 'uv_protection', 'add', 'spf_level', 'SPF 30 daily, PIH prevention primary', 'Type V skin very rarely burns; hyperpigmentation is main concern', 'A'),
(5, 'actives', 'prefer', 'acid_type', 'Mandelic acid preferred over glycolic', 'Mandelic acid has lower PIH risk in darker skin types', 'A'),
(5, 'actives', 'avoid', 'high_concentration_retinol', 'Lower retinol start, monitor for irritation', 'Higher melanin does not protect against retinoid irritation', 'B'),
(5, 'procedures', 'avoid', 'aggressive_laser', 'Conservative laser, avoid aggressive fractional', 'Type V skin has significant PIH and rare hypopigmentation risk', 'A'),
(5, 'supplements', 'add', 'vitamin_d', 'Vitamin D 2000 IU daily', 'Reduced vitamin D synthesis due to high melanin', 'B'),
(6, 'uv_protection', 'add', 'spf_level', 'SPF 30 daily, PIH and keloid awareness', 'Type VI skin never burns but hyperpigmentation and keloid risk', 'A'),
(6, 'actives', 'prefer', 'acid_type', 'Mandelic acid preferred, caution with all actives', 'Mandelic acid is safest for darkest skin types', 'A'),
(6, 'actives', 'avoid', 'aggressive_chemical_peels', 'Caution with deep peels', 'Deep chemical peels carry higher risk of complications in Type VI skin', 'A'),
(6, 'procedures', 'avoid', 'aggressive_energy', 'Minimal laser, prefer chemical approaches', 'Type VI skin has highest risk of PIH and hypopigmentation', 'A'),
(6, 'supplements', 'add', 'vitamin_d', 'Vitamin D 2000 IU daily', 'Minimal vitamin D synthesis due to very high melanin content', 'B')
INSERT INTO public.medication_skin_effects (medication_name, drug_class, skin_effects, skin_conditions_triggered, nutrients_depleted, supplements_to_add, supplements_to_avoid, plan_modifications, evidence_level, citation) VALUES
('Sertraline, Fluoxetine, Venlafaxine', 'ssri', ARRAY['dryness','photosensitivity','bruising','sweating'], ARRAY['xerosis','contact-dermatitis'], ARRAY['melatonin','coq10','b vitamins'], ARRAY['coq10 200mg','b-complex'], ARRAY[''], '{"dietary":["extra hydration"],"topical":["barrier cream","spf 50+"]}', 'A', 'SSRIs commonly cause xerosis and photosensitivity; deplete multiple nutrients'),
('Ethinyl estradiol combos', 'birth_control', ARRAY['melasma','hyperpigmentation','increased clotting risk'], ARRAY['melasma','post-inflammatory-hyperpigmentation'], ARRAY['b6','b12','folate','zinc','magnesium'], ARRAY['b-complex','folate 800mcg','zinc 15mg'], ARRAY[''], '{"dietary":["leafy greens","folate-rich foods"],"topical":["vitamin C serum","SPF 50+"]}', 'A', 'Oral contraceptives are well-documented melasma triggers and nutrient depleters'),
('Atorvastatin, Rosuvastatin', 'statin', ARRAY['dryness','coq10 depletion','fatigue'], ARRAY['xerosis'], ARRAY['coq10','vitamin_d'], ARRAY['coq10 200-300mg','vitamin_d 4000 iu'], ARRAY[''], '{"dietary":["coq10-rich foods","fatty fish"],"topical":["barrier repair"]}', 'A', 'Statins significantly deplete CoQ10 leading to fatigue and cellular energy deficits'),
('Isotretinoin', 'isotretinoin', ARRAY['extreme dryness','chapped lips','sun sensitivity','joint pain'], ARRAY['xerosis','photosensitivity'], ARRAY[''], ARRAY['omega-3 3g','vitamin_e 400iu','glucosamine'], ARRAY['vitamin_a'], '{"dietary":["extra hydration","omega-3 rich foods"],"topical":["heavy barrier cream","lip balm","spf 50+"]}', 'A', 'Isotretinoin requires comprehensive support due to multiple side effects'),
('Metformin', 'metformin', ARRAY['b12 depletion','dryness'], ARRAY['xerosis'], ARRAY['b12','folate','coq10'], ARRAY['b12 1000mcg sublingual','folate'], ARRAY[''], '{"dietary":["b12-rich foods","folate-rich foods"],"topical":["moisturizer"]}', 'A', 'Metformin significantly depletes B12 over time affecting skin and energy'),
('Cetirizine, Loratadine', 'antihistamine', ARRAY['dryness'], ARRAY['xerosis'], ARRAY[''], ARRAY['extra hydration','omega-3'], ARRAY[''], '{"dietary":["increase water intake"],"topical":["barrier repair moisturizer"]}', 'B', 'Antihistamines reduce secretions causing xerosis in susceptible individuals'),
('Metoprolol, Atenolol', 'beta_blocker', ARRAY['psoriasis flares','cold extremities','hair loss'], ARRAY['psoriasis','hair-loss'], ARRAY['coq10'], ARRAY['coq10 200mg'], ARRAY[''], '{"dietary":["coq10-rich foods"],"topical":["scalp treatments","warming measures"]}', 'B', 'Beta-blockers are known psoriasis triggers and deplete CoQ10'),
('Prednisone', 'corticosteroid', ARRAY['thinning skin','easy bruising','delayed wound healing','stretch marks'], ARRAY['xerosis','skin fragility'], ARRAY['calcium','vitamin_d','potassium'], ARRAY['calcium 1000mg','vitamin_d 5000 iu'], ARRAY[''], '{"dietary":["calcium-rich foods","vitamin D foods","potassium-rich foods"],"topical":["gentle care","avoid harsh actives"]}', 'A', 'Corticosteroids cause well-documented skin thinning and nutrient depletion'),
('Furosemide, HCTZ', 'diuretic', ARRAY['dehydration','electrolyte imbalance'], ARRAY['xerosis','dullness'], ARRAY['potassium','magnesium','sodium'], ARRAY['magnesium 400mg'], ARRAY[''], '{"dietary":["potassium-rich foods","hydration focus"],"topical":["intensive moisturizer"]}', 'A', 'Diuretics cause electrolyte imbalance affecting skin hydration'),
('Ibuprofen, Naproxen', 'nsaid', ARRAY['gi permeability','systemic inflammation'], ARRAY['acne-vulgaris','atopic-dermatitis'], ARRAY['folate','iron'], ARRAY['probiotics','l-glutamine 5g'], ARRAY[''], '{"dietary":["gut-healing foods","probiotic foods"],"topical":["anti-inflammatory support"]}', 'B', 'NSAIDs increase intestinal permeability contributing to systemic inflammation'),
('Levothyroxine', 'thyroid_medication', ARRAY['dose-dependent skin changes'], ARRAY['xerosis','oily skin'], ARRAY['calcium','iron'], ARRAY[''], ARRAY['calcium','iron'], '{"dietary":["take supplements 4h apart from thyroid med"],"topical":["adjust based on thyroid status"]}', 'A', 'Thyroid medication dosing directly affects skin condition; supplement timing critical'),
('Lisinopril', 'ace_inhibitor', ARRAY['cough','throat dryness','rare angioedema'], ARRAY['xerosis'], ARRAY['zinc'], ARRAY['zinc 15mg'], ARRAY[''], '{"dietary":["zinc-rich foods"],"topical":["moisturizer"]}', 'B', 'ACE inhibitors cause cough and throat dryness; chronic use may deplete zinc'),
('Doxycycline, Minocycline', 'antibiotic', ARRAY['photosensitivity','yeast overgrowth','gut disruption'], ARRAY['photosensitivity','yeast-infection'], ARRAY['b vitamins','probiotics'], ARRAY['probiotic 50B+ CFU','b-complex'], ARRAY[''], '{"dietary":["probiotic foods","b-vitamin rich foods"],"topical":["spf 50+","gentle care"]}', 'A', 'Tetracycline antibiotics cause photosensitivity and gut dysbiosis'),
('Semaglutide, Tirzepatide', 'glp1_agonist', ARRAY['volume loss','gi symptoms','dryness'], ARRAY['premature-aging','xerosis'], ARRAY['b12','protein'], ARRAY['b12 1000mcg','collagen 15g'], ARRAY[''], '{"dietary":["protein focus","collagen-rich foods","b12 foods"],"topical":["volume-supporting treatments","intensive moisturizer"]}', 'B', 'GLP-1 agonists cause facial volume loss and potential nutrient deficiencies')
INSERT INTO public.oral_microbiome_protocols (id, name, description, protocol_type, target_conditions, instructions, oral_probiotic_strains, evidence_level, citation) VALUES
('oral-probiotic-lozenges', 'Oral Probiotic Lozenges', 'Targeted oral probiotic strains that reduce oral inflammation and systemic inflammatory load affecting rosacea and perioral dermatitis', 'probiotic', ARRAY['rosacea','perioral-dermatitis','acne-vulgaris'], 'Dissolve 1 oral probiotic lozenge daily after brushing. Contains L. reuteri and S. salivarius K12. Do not eat or drink for 30 minutes after.', ARRAY['Lactobacillus reuteri','Streptococcus salivarius K12'], 'B', 'Oral probiotics show emerging evidence for rosacea and perioral dermatitis improvement'),
('tongue-scraping', 'Daily Tongue Scraping', 'Mechanical removal of bacterial biofilm from tongue surface reduces systemic inflammatory load', 'hygiene', ARRAY['rosacea','acne-vulgaris','general-skin-health'], 'Use stainless steel tongue scraper every morning before brushing. Scrape from back of tongue to front 5-10 times. Rinse scraper between passes.', ARRAY[''], 'B', 'Tongue scraping reduces oral bacterial load and volatile sulfur compounds'),
('sls-free-toothpaste', 'SLS-Free Toothpaste', 'Sodium lauryl sulfate-free toothpaste reduces perioral irritation and mouth ulcers that can trigger skin inflammation', 'hygiene', ARRAY['perioral-dermatitis','sensitive-skin'], 'Switch to SLS-free toothpaste. Brush twice daily. Monitor perioral area for 2-4 weeks for improvement.', ARRAY[''], 'B', 'SLS is a known irritant that can trigger perioral dermatitis in susceptible individuals'),
('oil-pulling', 'Oil Pulling (Coconut Oil)', 'Traditional practice of swishing oil to reduce oral bacterial load with potential systemic benefits', 'lifestyle', ARRAY['acne-vulgaris','general-skin-health'], 'Swish 1 tablespoon coconut oil in mouth for 10-15 minutes. Do not swallow. Spit into trash (not sink). Rinse with warm water. Perform daily on empty stomach.', ARRAY[''], 'C', 'Oil pulling reduces oral bacteria load; limited direct evidence for skin improvement'),
('oral-zinc', 'Zinc for Oral Health', 'Zinc supplementation supports immune function in oral cavity and reduces bacterial overgrowth', 'supplement', ARRAY['acne-vulgaris','rosacea','general-skin-health'], 'Take 15mg zinc picolinate daily with food. Can combine with oral probiotic protocol for enhanced effect.', ARRAY[''], 'B', 'Zinc supports immune function and wound healing at mucosal surfaces'),
('oral-collagen', 'Collagen for Gum Health', 'Collagen peptide supplementation strengthens gum tissue integrity and reduces oral inflammation', 'supplement', ARRAY['general-skin-health','gum-health'], 'Take 10g collagen peptides daily. Can mix into coffee, tea, or water. Supports both gum tissue and systemic skin collagen.', ARRAY[''], 'B', 'Collagen supplementation supports connective tissue integrity including oral mucosa')
