('summer', 'temperate', 'actives', 'Reduce retinol strength, increase AHA for sweat/exfoliation', 'Higher temperatures increase sensitivity to retinoids; sweat benefits from gentle exfoliation', 'medium'),
('summer', 'temperate', 'uv_defense', 'SPF 50+, reapply every 2h, hat and sunglasses', 'Peak UV exposure requires maximum protection', 'high'),
('summer', 'temperate', 'supplements', 'Add antioxidants (vitamin C, astaxanthin)', 'Increased UV exposure raises oxidative stress', 'medium'),
('fall', 'temperate', 'hydration', 'Return to baseline water target, transition moisture', 'Reduced heat exposure lowers hydration needs; air becomes drier', 'medium'),
('fall', 'temperate', 'actives', 'Resume higher retinol, add vitamin C serum', 'Post-summer recovery period ideal for retinoid reintroduction', 'medium'),
('fall', 'temperate', 'uv_defense', 'Maintain SPF 30-50', 'UV still significant, especially at lower sun angles', 'high'),
('fall', 'temperate', 'supplements', 'Shift to immune support (zinc, vitamin D3)', 'Cold and flu season approaches; immune support benefits skin', 'medium'),
('winter', 'temperate', 'hydration', '+30% water target, add humidifier', 'Dry heating air significantly increases transepidermal water loss', 'high'),
('winter', 'temperate', 'actives', 'Reduce AHA frequency, richer moisturizer, hyaluronic acid', 'Cold dry air increases sensitivity; barrier support critical', 'medium'),
('winter', 'temperate', 'uv_defense', 'SPF 30 (UV still present, especially at altitude)', 'Snow reflection and altitude increase UV exposure', 'high'),
('winter', 'temperate', 'supplements', 'Extra omega-3 (barrier support), vitamin D 5000 IU', 'Reduced sun exposure lowers vitamin D; dry air benefits from omega-3', 'high'),
('spring', 'temperate', 'hydration', '+10% target, allergen awareness', 'Allergen season may increase inflammation and histamine response', 'medium'),
('spring', 'temperate', 'actives', 'Gradual retinol increase, add niacinamide', 'Post-winter skin recovery with barrier-supporting ingredients', 'medium'),
('spring', 'temperate', 'uv_defense', 'SPF 30-50, reapply as outdoor activity increases', 'Increasing sun exposure and outdoor time', 'high'),
('spring', 'temperate', 'supplements', 'Quercetin (antihistamine), probiotics (allergy-gut-skin)', 'Allergy season support through mast cell stabilization and gut health', 'medium')
INSERT INTO public.gut_brain_skin_protocols (id, name, description, targets_gut, targets_brain, targets_skin, protocol_type, intervention_details, mechanism_chain, conditions_treated, evidence_level, citation) VALUES
('gbs-psychobiotic', 'Psychobiotic Stack', 'Combined probiotic approach targeting the stress-gut-skin axis through vagal tone and microbiome modulation', TRUE, TRUE, TRUE, 'probiotic', '{"strains":["L. rhamnosus GG","B. longum"],"dose":"10-20B CFU/day","timing":"morning empty stomach"}', 'Stress → vagal tone ↓ → gut dysbiosis → LPS ↑ → inflammation → acne/eczema', ARRAY['acne-vulgaris','atopic-dermatitis','rosacea'], 'A', 'Psychobiotics demonstrate bidirectional gut-brain-skin benefits in clinical trials'),
('gbs-lglutamine-gut', 'L-Glutamine Gut Repair', 'Amino acid protocol for intestinal barrier repair and endotoxemia reduction', TRUE, FALSE, TRUE, 'supplement', '{"dose":"5-10g/day","timing":"morning empty stomach","duration":"8 weeks"}', 'Stress → intestinal permeability → endotoxemia → systemic inflammation → skin', ARRAY['acne-vulgaris','atopic-dermatitis'], 'B', 'L-glutamine supports tight junction integrity and reduces intestinal permeability'),
('gbs-ashwagandha-triad', 'Ashwagandha (Gut-Brain-Skin)', 'Adaptogenic approach to cortisol reduction with downstream gut and skin benefits', TRUE, TRUE, TRUE, 'adaptogen', '{"dose":"300-600mg KSM-66","timing":"evening with food","duration":"12 weeks"}', 'Cortisol ↓ → gut motility normalized → microbiome diversity ↑ → skin inflammation ↓', ARRAY['acne-vulgaris','atopic-dermatitis','premature-aging'], 'A', 'Ashwagandha reduces cortisol and improves gut-skin axis through HPA modulation'),
('gbs-zinc-carnosine', 'Zinc Carnosine (Gut Barrier)', 'Targeted gut barrier repair with anti-inflammatory benefits at mucosal level', TRUE, FALSE, TRUE, 'supplement', '{"dose":"75mg 2x/day","timing":"between meals","duration":"8 weeks"}', 'Repairs tight junctions, reduces permeability, anti-inflammatory at gut level', ARRAY['acne-vulgaris','rosacea','atopic-dermatitis'], 'B', 'Zinc carnosine demonstrates gut barrier repair in clinical GI studies'),
('gbs-omega3-resolution', 'Omega-3 Resolution Protocol', 'High-dose EPA/DHA for specialized pro-resolving mediator production across all three axes', TRUE, TRUE, TRUE, 'supplement', '{"dose":"3g combined EPA/DHA","timing":"with meals","duration":"12 weeks"}', 'EPA/DHA → specialized pro-resolving mediators → inflammation resolution at all 3 sites', ARRAY['acne-vulgaris','psoriasis','atopic-dermatitis','rosacea'], 'A', 'Omega-3 derived SPMs actively resolve inflammation in gut, brain, and skin tissues'),
('gbs-berberine-metabolic', 'Berberine Metabolic Reset', 'AMPK-activating approach to gut motility and SIBO reduction with skin clarity benefits', TRUE, FALSE, TRUE, 'supplement', '{"dose":"500mg 2-3x/day","timing":"with meals","duration":"12 weeks"}', 'AMPK activation → gut motility ↑ → SIBO reduction → skin clarity', ARRAY['acne-vulgaris','rosacea'], 'A', 'Berberine improves gut motility and reduces bacterial overgrowth with skin benefits'),
('gbs-mindful-eating', 'Mindful Eating Protocol', 'Vagal activation through conscious eating practices to improve digestion and nutrient absorption', TRUE, TRUE, FALSE, 'lifestyle', '{"duration":"20 minutes per meal","practice":"chew thoroughly","environment":"no screens"}', 'Vagal activation → improved digestion → nutrient absorption → skin nourishment', ARRAY['general-skin-health','nutrient-deficiency'], 'B', 'Mindful eating improves vagal tone and digestive efficiency with downstream skin benefits'),
('gbs-combined-reset', '21-Day Gut-Brain-Skin Reset', 'Comprehensive integrated protocol combining elimination diet, psychobiotic, adaptogen, and sleep optimization', TRUE, TRUE, TRUE, 'combined', '{"phase1":"elimination diet (days 1-7)","phase2":"psychobiotic + adaptogen (days 8-14)","phase3":"sleep optimization + reintroduction (days 15-21)"}', 'Full protocol: elimination diet + psychobiotic + adaptogen + sleep optimization', ARRAY['acne-vulgaris','atopic-dermatitis','rosacea','premature-aging'], 'B', 'Combined protocols show synergistic benefits greater than individual interventions')
INSERT INTO public.sun_exposure_protocols (id, name, description, time_window, duration_minutes_min, duration_minutes_max, body_areas_exposed, face_protection, sunscreen_on_body, sunglasses, d3_synthesis, circadian_benefit, melatonin_impact, mitochondrial_benefit, nitric_oxide, serotonin_impact, uv_risk, photoaging_risk, cancer_risk, fitzpatrick_duration, beneficial_for, contraindicated_for, evidence_level, citation) VALUES
('am-circadian-reset', 'Morning Circadian Reset', 'Early morning sun exposure for circadian rhythm entrainment with minimal UV risk', '6-8 AM', 10, 20, ARRAY['arms','legs','face'], 'none', 'none', FALSE, 'low', 'high', 'positive', 'moderate', 'moderate', 'high', 'very_low', 'minimal', 'minimal', '{"I":10,"II":12,"III":15,"IV":20,"V":25,"VI":30}', ARRAY['sleep-issues','mood-disorders','premature-aging'], ARRAY['melasma','photosensitivity'], 'A', 'Morning light exposure robustly entrains circadian rhythm and improves sleep quality'),
('am-d3-synthesis', 'Morning D3 Synthesis Window', 'Optimal morning window for vitamin D3 synthesis with low UVB risk', '8-10 AM', 15, 30, ARRAY['arms','legs','back'], 'spf_30', 'none', FALSE, 'moderate', 'moderate', 'positive', 'low', 'moderate', 'moderate', 'low', 'low', 'low', '{"I":15,"II":15,"III":20,"IV":25,"V":30,"VI":30}', ARRAY['vitamin-d-deficiency','bone-health','immune-support'], ARRAY['melasma','lupus'], 'A', 'Morning UVB exposure produces vitamin D3 with lower photoaging risk than midday'),
('midday-d3-boost', 'Midday D3 Boost (Controlled)', 'Short controlled midday exposure for maximum D3 synthesis efficiency', '10 AM-2 PM', 5, 15, ARRAY['arms','legs'], 'spf_50', 'none', TRUE, 'high', 'low', 'neutral', 'low', 'high', 'low', 'moderate', 'moderate', 'moderate', '{"I":5,"II":8,"III":10,"IV":12,"V":15,"VI":15}', ARRAY['severe-vitamin-d-deficiency'], ARRAY['melasma','photosensitivity','skin-cancer-history'], 'A', 'Midday exposure maximizes D3 synthesis per minute but requires strict time limits'),
('pm-red-nir', 'Afternoon Red/NIR Exposure', 'Late afternoon exposure leveraging longer wavelengths for mitochondrial support', '4-6 PM', 15, 30, ARRAY['arms','legs','face'], 'none', 'none', FALSE, 'low', 'low', 'positive', 'high', 'high', 'high', 'low', 'low', 'low', '{"I":15,"II":15,"III":20,"IV":20,"V":25,"VI":25}', ARRAY['mitochondrial-dysfunction','fatigue','premature-aging'], ARRAY['photosensitivity'], 'B', 'Late afternoon light contains significant red/NIR wavelengths beneficial for mitochondria'),
('body-d3-protocol', 'Body D3 Protocol (Face Protected)', 'Body-focused exposure with face always protected to minimize facial photoaging', '8-10 AM', 15, 20, ARRAY['arms','legs','back'], 'spf_50', 'none', FALSE, 'moderate', 'moderate', 'positive', 'low', 'moderate', 'moderate', 'low', 'low', 'low', '{"I":15,"II":15,"III":20,"IV":20,"V":25,"VI":25}', ARRAY['vitamin-d-deficiency','premature-aging-prevention'], ARRAY['melasma'], 'A', 'Protecting face while exposing body optimizes D3 while minimizing facial photoaging'),
('weekend-extended', 'Weekend Extended Exposure', 'Longer duration morning exposure for cumulative D3 and social outdoor benefits', '7-9 AM', 30, 45, ARRAY['arms','legs','chest','back'], 'spf_30', 'spf_15', FALSE, 'high', 'high', 'positive', 'moderate', 'moderate', 'high', 'low', 'low', 'low', '{"I":30,"II":30,"III":35,"IV":40,"V":45,"VI":45}', ARRAY['vitamin-d-deficiency','mood-support','social-connection'], ARRAY['melasma','lupus'], 'B', 'Weekend extended exposure provides cumulative D3 benefits with social and mood enhancement')
